// Checks a workflow before it is used. The same checks run on workflows built
// by hand, imported as JSON, or generated by AI, so AI output is never trusted
// blindly: every rule must parse, every variable it reads must exist, and every
// template must be well formed.

import { referencedPaths, type Node } from "./expr.ts";
import { compile } from "./session.ts";
import { parseTemplate, templateExprs } from "./template.ts";
import type { Computed, DocTemplate, Field, Option, Page, Question, QuestionType, Workflow } from "./types.ts";

export interface Issue {
  level: "error" | "warning";
  where: string;
  message: string;
}

export interface ValidateOptions {
  /** Known case-record paths (e.g. `client.name`). When given, `case.*` references are checked against them. */
  caseFields?: string[];
}

export const QUESTION_TYPES: QuestionType[] = ["text", "textarea", "number", "currency", "date", "yesno", "choice", "multichoice", "list"];
const ID_RE = /^[A-Za-z_][A-Za-z0-9_]*$/;
const RESERVED = new Set(["case", "loop", "true", "false", "null", "and", "or", "not", "contains", "in"]);
const LOOP_PROPS = new Set(["index", "first", "last", "count"]);

// ------------------------------------------------------------ normalizing

const str = (v: unknown): string => (typeof v === "string" ? v : v === undefined || v === null ? "" : String(v));
const opt = (v: unknown): string | undefined => (str(v).trim() === "" ? undefined : str(v));
const arr = (v: unknown): unknown[] => (Array.isArray(v) ? v : []);
const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});

function options(v: unknown): Option[] {
  return arr(v).map((o) => {
    const r = obj(o);
    const value = str(r.value ?? r.label);
    return { value, label: str(r.label) || value };
  });
}

function field(v: unknown): Field {
  const r = obj(v);
  const f: Field = { id: str(r.id), label: str(r.label), type: str(r.type) as Field["type"] };
  if (f.type === "choice" || f.type === "multichoice") f.options = options(r.options);
  if (r.required === true) f.required = true;
  return f;
}

function question(v: unknown): Question {
  const r = obj(v);
  const q: Question = { id: str(r.id), label: str(r.label), type: str(r.type) as QuestionType };
  const help = opt(r.help);
  if (help) q.help = help;
  if (r.required === true) q.required = true;
  if (q.type === "choice" || q.type === "multichoice") q.options = options(r.options);
  const showIf = opt(r.showIf);
  if (showIf) q.showIf = showIf;
  const prefill = opt(r.prefill);
  if (prefill) q.prefill = prefill;
  if (q.type === "list") q.fields = arr(r.fields).map(field);
  return q;
}

/**
 * Coerces untrusted JSON (an import, or AI output) into the workflow shape.
 * Empty strings become absent optional fields; unknown keys are dropped.
 */
export function normalizeWorkflow(raw: unknown): Workflow {
  const r = obj(raw);
  const wf: Workflow = {
    id: str(r.id) || "workflow",
    name: str(r.name) || "Untitled workflow",
    pages: arr(r.pages).map((p, i): Page => {
      const pr = obj(p);
      const page: Page = { id: str(pr.id) || `page_${i + 1}`, title: str(pr.title), questions: arr(pr.questions).map(question) };
      const showIf = opt(pr.showIf);
      if (showIf) page.showIf = showIf;
      return page;
    }),
    computed: arr(r.computed).map((c): Computed => {
      const cr = obj(c);
      const out: Computed = { id: str(cr.id), expr: str(cr.expr) };
      const label = opt(cr.label);
      if (label) out.label = label;
      return out;
    }),
    documents: arr(r.documents).map((d, i): DocTemplate => {
      const dr = obj(d);
      const doc: DocTemplate = { id: str(dr.id) || `doc_${i + 1}`, name: str(dr.name), body: str(dr.body) };
      const showIf = opt(dr.showIf);
      if (showIf) doc.showIf = showIf;
      return doc;
    }),
  };
  const description = opt(r.description);
  if (description) wf.description = description;
  return wf;
}

// ------------------------------------------------------------- validating

export function validateWorkflow(wf: Workflow, opts: ValidateOptions = {}): Issue[] {
  const issues: Issue[] = [];
  const err = (where: string, message: string) => issues.push({ level: "error", where, message });
  const warn = (where: string, message: string) => issues.push({ level: "warning", where, message });

  const questions = new Map<string, { q: Question; pageIndex: number; order: number }>();
  const computed = new Map<string, Computed>();
  const used = new Set<string>();
  let order = 0;

  // Names
  const seen = new Set<string>();
  const claim = (id: string, where: string) => {
    if (!ID_RE.test(id)) err(where, `"${id}" is not a valid name. Use letters, numbers and underscores, starting with a letter.`);
    else if (RESERVED.has(id)) err(where, `"${id}" is a reserved word.`);
    else if (seen.has(id)) err(where, `The name "${id}" is used more than once.`);
    seen.add(id);
  };

  if (wf.pages.length === 0) warn("Workflow", "There are no pages, so the interview asks nothing.");

  const pageIds = new Set<string>();
  wf.pages.forEach((page, pageIndex) => {
    const where = `Page "${page.title || page.id}"`;
    if (pageIds.has(page.id)) err(where, `Page id "${page.id}" is used more than once.`);
    pageIds.add(page.id);
    if (page.questions.length === 0) warn(where, "This page has no questions.");
    for (const q of page.questions) {
      const qWhere = `Question "${q.id}"`;
      claim(q.id, qWhere);
      questions.set(q.id, { q, pageIndex, order: order++ });
      if (!q.label.trim()) warn(qWhere, "The question has no label.");
      if (!QUESTION_TYPES.includes(q.type)) err(qWhere, `Unknown question type "${q.type}".`);
      checkOptions(q.type, q.options, qWhere, err);
      if (q.type === "list") {
        if (!q.fields || q.fields.length === 0) err(qWhere, "A list needs at least one field to ask for each item.");
        const fieldIds = new Set<string>();
        for (const f of q.fields ?? []) {
          const fWhere = `${qWhere}, field "${f.id}"`;
          if (!ID_RE.test(f.id)) err(fWhere, `"${f.id}" is not a valid field name.`);
          if (fieldIds.has(f.id)) err(fWhere, `The field "${f.id}" is used more than once.`);
          fieldIds.add(f.id);
          if (!QUESTION_TYPES.includes(f.type) || (f.type as QuestionType) === "list") err(fWhere, `Field type "${f.type}" is not allowed in a list.`);
          checkOptions(f.type, f.options, fWhere, err);
        }
      }
    }
  });
  for (const c of wf.computed) {
    claim(c.id, `Computed "${c.id}"`);
    computed.set(c.id, c);
  }

  // Checks one expression: it parses, and every name it reads exists.
  const check = (src: string, where: string, context: { loops?: Map<string, Node>; self?: string; caseOnly?: boolean } = {}): Node | null => {
    const node = compile(src);
    if (node instanceof Error) {
      err(where, `${node.message} in "${src}".`);
      return null;
    }
    checkPaths(referencedPaths(node), where, context);
    return node;
  };

  const checkPaths = (paths: string[][], where: string, context: { loops?: Map<string, Node>; self?: string; caseOnly?: boolean }) => {
    for (const path of paths) {
      const [root, prop] = path;
      if (root === "case") {
        if (opts.caseFields && path.length > 1 && !opts.caseFields.some((f) => f === path.slice(1).join(".") || f.startsWith(path.slice(1).join(".") + ".")))
          warn(where, `The case record has no field "${path.join(".")}".`);
        continue;
      }
      if (context.caseOnly) {
        err(where, `Pre-fill can only read the case record (case.*), not "${root}".`);
        continue;
      }
      const loopList = context.loops?.get(root);
      if (loopList) {
        if (prop && loopList.kind === "var") checkField(loopList.name, prop, where);
        continue;
      }
      if (root === "loop" && context.loops?.size) {
        if (prop && !LOOP_PROPS.has(prop)) err(where, `"loop.${prop}" doesn't exist. Use loop.index, loop.first, loop.last or loop.count.`);
        continue;
      }
      if (root === context.self) {
        err(where, `"${root}" refers to itself.`);
        continue;
      }
      used.add(root);
      if (questions.has(root)) {
        if (prop) checkField(root, prop, where);
      } else if (!computed.has(root)) {
        err(where, `"${root}" is not a question or computed value.`);
      }
    }
  };

  const checkField = (listId: string, prop: string, where: string) => {
    const entry = questions.get(listId);
    if (!entry || entry.q.type !== "list") return;
    if (!(entry.q.fields ?? []).some((f) => f.id === prop)) err(where, `The list "${listId}" has no field "${prop}".`);
  };

  // Rules on pages and questions
  wf.pages.forEach((page, pageIndex) => {
    if (page.showIf) {
      const node = check(page.showIf, `Page "${page.title || page.id}" show-if`);
      if (node) warnLater(node, pageIndex, -1, `Page "${page.title || page.id}" show-if`);
    }
    for (const q of page.questions) {
      if (q.showIf) {
        const node = check(q.showIf, `Question "${q.id}" show-if`, { self: q.id });
        if (node) warnLater(node, pageIndex, questions.get(q.id)!.order, `Question "${q.id}" show-if`);
      }
      if (q.prefill) check(q.prefill, `Question "${q.id}" pre-fill`, { caseOnly: true });
    }
  });

  // A show-if that reads a question asked later can't see its answer yet.
  function warnLater(node: Node, pageIndex: number, ownOrder: number, where: string) {
    for (const [root] of referencedPaths(node)) {
      const entry = questions.get(root);
      if (!entry) continue;
      const later = entry.pageIndex > pageIndex || (entry.pageIndex === pageIndex && (ownOrder === -1 || entry.order > ownOrder));
      if (later) warn(where, `It reads "${root}", which is asked later, so it will still be unanswered at this point.`);
    }
  }

  // Computed values
  for (const c of wf.computed) check(c.expr, `Computed "${c.id}"`, { self: c.id });
  for (const cycle of computedCycles(wf.computed)) err(`Computed "${cycle[0]}"`, `Computed values depend on each other in a circle: ${cycle.join(" → ")}.`);

  // Documents
  for (const doc of wf.documents) {
    const where = `Document "${doc.name || doc.id}"`;
    if (doc.showIf) check(doc.showIf, `${where} show-if`);
    try {
      for (const { expr, loops } of templateExprs(parseTemplate(doc.body))) checkPaths(referencedPaths(expr), where, { loops });
    } catch (e) {
      err(where, (e as Error).message);
    }
  }
  for (const c of wf.computed) {
    const node = compile(c.expr);
    if (!(node instanceof Error)) for (const [root] of referencedPaths(node)) used.add(root);
  }
  if (wf.documents.length === 0) warn("Workflow", "There are no documents yet.");

  for (const [id, { q }] of questions) {
    if (!used.has(id)) warn(`Question "${id}"`, `"${q.label || id}" is asked but never used in a rule, computed value or document.`);
  }

  return issues;
}

function checkOptions(type: string, options: Option[] | undefined, where: string, err: (w: string, m: string) => void) {
  if (type !== "choice" && type !== "multichoice") return;
  if (!options || options.length === 0) {
    err(where, "A choice question needs at least one option.");
    return;
  }
  const values = new Set<string>();
  for (const o of options) {
    if (!o.value.trim()) err(where, `Option "${o.label}" has no value.`);
    if (values.has(o.value)) err(where, `The option value "${o.value}" is used more than once.`);
    values.add(o.value);
  }
}

function computedCycles(list: Computed[]): string[][] {
  const deps = new Map<string, string[]>();
  for (const c of list) {
    const node = compile(c.expr);
    deps.set(c.id, node instanceof Error ? [] : referencedPaths(node).map((p) => p[0]).filter((n) => n !== c.id));
  }
  const cycles: string[][] = [];
  const state = new Map<string, "visiting" | "done">();
  const stack: string[] = [];
  const visit = (id: string) => {
    if (state.get(id) === "done") return;
    if (state.get(id) === "visiting") {
      cycles.push([...stack.slice(stack.indexOf(id)), id]);
      return;
    }
    state.set(id, "visiting");
    stack.push(id);
    for (const d of deps.get(id) ?? []) if (deps.has(d)) visit(d);
    stack.pop();
    state.set(id, "done");
  };
  for (const c of list) visit(c.id);
  return cycles;
}
